package com.cyancoder.storefront.controller;
import com.cyancoder.storefront.api.DomainContracts.*; import com.cyancoder.storefront.model.*; import com.cyancoder.storefront.service.DomainRegistryService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/endpoint/domains") public class EndpointDomainController {private final DomainRegistryService service;public EndpointDomainController(DomainRegistryService s){service=s;}@GetMapping public List<DomainBindingEntity> list(@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a){return service.list(t,s,a.getName());}@PostMapping @ResponseStatus(HttpStatus.CREATED) public DomainBindingEntity create(@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a,@Valid @RequestBody CreateDomainRequest r){return service.create(t,s,a.getName(),r);}@GetMapping("/{id}/dns-instructions")public List<DnsInstruction> instructions(@PathVariable Long id,@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a){return service.instructions(id,t,s,a.getName());}@PostMapping("/{id}/verify")public DomainBindingEntity verify(@PathVariable Long id,@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a){return service.verify(id,t,s,a.getName());}@GetMapping("/{id}/history")public List<DomainEventEntity> history(@PathVariable Long id,@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a){return service.history(id,t,s,a.getName());}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void remove(@PathVariable Long id,@RequestHeader("X-Tenant-Key")String t,@RequestHeader("X-Site-Key")String s,Authentication a){service.remove(id,t,s,a.getName());}}
